export const BODY: string = "\n<p>تصویر کی چمک درست کرنا صرف چند منٹ کا کام ہے۔ آپ تصویر اپ لوڈ کرتے ہیں، سلائیڈر کو کھینچتے ہیں، نتیجہ دیکھتے ہیں اور روشن نسخہ ڈاؤن لوڈ کر لیتے ہیں۔</p>\n<p>یہ رہنمائی پورا عمل قدم بہ قدم سمجھاتی ہے۔ اس میں سلائیڈر، فوری پری سیٹس، موازنے کے طریقے اور ایکسپورٹ کی ترتیبات شامل ہیں، تاکہ نتیجہ صاف رہے۔</p>\n<p>آخر تک آپ اندھیری پورٹریٹ، پھیکی لینڈ سکیپ یا دھندلی اسکرین شاٹ کسی بھی ڈیوائس پر ٹھیک کر سکیں گے۔ اصل تصویر اس وقت تک رکھیں، جب تک نتیجہ جانچ نہ لیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: اندھیرا کتنا ہے، یہ جانچیں</h2>\n<p>ٹول کھولنے سے پہلے تصویر کو غور سے دیکھیں۔ کیا وہ ہلکی سی اندھیری ہے، بہت زیادہ اندھیری ہے، یا صرف ایک حصہ اندھیرا ہے؟ اس جواب سے معلوم ہوتا ہے کہ کتنی روشنی چاہیے۔</p>\n<p>ہلکی سی اندھیری تصویر کو دس سے پندرہ فیصد چاہیے۔ بہت زیادہ اندھیری تصویر کو تیس فیصد یا اس سے زیادہ درکار ہو سکتا ہے، مگر بڑی تبدیلی سے روشن حصے دھل سکتے ہیں۔</p>\n<p>یہ بھی دیکھیں کہ تصویر پھیکی یا بے جان تو نہیں۔ اندھیری اور پھیکی تصویر کو چمک اور کنٹراسٹ دونوں چاہئیں، اس لیے دونوں تبدیلیوں کی منصوبہ بندی کریں، صرف ایک کی نہیں۔</p>\n<p>اپنے براؤزر میں <a href=\"/ur/tasveer-ki-brightness-badlein/\">Image Brightness Editor</a> کھولیں۔ سب کچھ مقامی طور پر چلتا ہے، اس لیے آپ کی تصویر کبھی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<h2 id=\"step-by-step\">پانچ مراحل میں چمک درست کریں</h2>\n<p>تصویر، اسکرین شاٹ یا اسکین شدہ دستاویز کے لیے طریقہ ایک ہی ہے۔ اپ لوڈ کریں، درست کریں، موازنہ کریں، ایکسپورٹ کریں اور ڈاؤن لوڈ کی تصدیق کریں۔</p>\n<p>سلائیڈر کے ساتھ وقت لیں۔ چھوٹی حرکت بھی بڑا فرق ڈالتی ہے، اور پری ویو بالکل بتا دیتا ہے کہ تصویر کب درست لگتی ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھولیں۔ تصدیق کریں کہ تصویر قدرتی روشنی والی لگے اور کوئی روشن حصہ سفید نہ ہو گیا ہو۔</p>\n<h2 id=\"using-the-slider\">چمک والا سلائیڈر کیسے استعمال کریں</h2>\n<p>سلائیڈر منفی سے مثبت اقدار تک چلتا ہے، جہاں صفر کا مطلب کوئی تبدیلی نہیں۔ دائیں کھینچنے سے تصویر روشن ہوتی ہے اور بائیں کھینچنے سے اندھیری ہوتی ہے۔</p>\n<p>آہستہ کھینچیں اور پری ویو دیکھتے رہیں۔ براہ راست اپ ڈیٹ بالکل دکھاتا ہے کہ تصویر کیسے بدلتی ہے، اس لیے اسی مقام پر رک جائیں جہاں تصویر درست لگے۔</p>\n<p>چھوٹی تبدیلیاں بڑی سے بہتر ہوتی ہیں۔ دس سے پندرہ فیصد کی تبدیلی اکثر کافی ہوتی ہے، اور بڑی تبدیلی روشن حصوں کو جلد دھو دیتی ہے۔</p>\n<p>اپ لوڈ کے فوراً بعد ٹول آپ کی تصویر کو جمع پندرہ فیصد پر دکھاتا ہے۔ یہ ابتدائی نقطہ فوراً بتاتا ہے کہ مناسب چمک کیسی لگتی ہے۔</p>\n<h2 id=\"using-quick-presets\">فوری پری سیٹس کیسے استعمال کریں</h2>\n<p>ٹول میں فوری پری سیٹس ہیں جو عام چمک کی اقدار ایک کلک میں لگا دیتے ہیں۔ یہ سلائیڈر کھینچے بغیر مختلف سطحیں جانچنے کا تیز طریقہ ہیں۔</p>\n<p>کسی پری سیٹ پر کلک کریں اور پری ویو دیکھیں۔ اگر نتیجہ قریب ہو مگر بالکل درست نہ ہو، تو وہیں سے سلائیڈر سے باریک درستی کر لیں۔</p>\n<p>پری سیٹس سے اختیارات کا موازنہ جلدی کریں۔ جمع پندرہ فیصد والا پری سیٹ، جمع تیس فیصد والے کے ساتھ رکھ کر دیکھیں کہ تصویر کتنی چمک برداشت کر سکتی ہے۔</p>\n<p>ملتی جلتی تصویروں کے بیچ کے لیے ایک ہی پری سیٹ نتیجہ مستقل رکھتا ہے۔ اندھیرے اندرونی مناظر کی تصاویر اگر ایک ہی مقدار سے روشن کی جائیں تو وہ ایک سیریز لگتی ہیں۔</p>\n<h2 id=\"using-compare-modes\">موازنے کے طریقے کیسے استعمال کریں</h2>\n<p>موازنے کے طریقے اصل اور تبدیل شدہ نسخہ ساتھ دکھاتے ہیں۔ بعد والی نظر روشن تصویر دکھاتی ہے اور پہلے والی نظر اصل تصویر دکھاتی ہے۔</p>\n<p>چمک کے کام کے لیے اسپلٹ موازنہ سب سے مفید ہے۔ یہ دونوں نسخے ایک واضح لکیر کے ساتھ ساتھ دکھاتا ہے، اس لیے آپ بالکل دیکھ سکتے ہیں کہ کیا بدلا۔</p>\n<p>فل اسکرین موازنہ سب سے بڑا نظارہ دیتا ہے۔ روشن تصویر کو پرکھنے کا یہ بہترین طریقہ ہے، کیونکہ مکمل سائز کی تصویر وہ تفصیل دکھاتی ہے جو چھوٹا پری ویو چھپا دیتا ہے۔</p>\n<p>ہر ڈاؤن لوڈ سے پہلے موازنے والی نظر ضرور دیکھیں۔ ایک تیز نظر اس زیادہ چمک کو پکڑ لیتی ہے جو چھوٹے پری ویو میں چھپ جائے۔</p>\n<h2 id=\"brightening-a-dark-photo\">اندھیری تصویر کو روشن کرنا</h2>\n<p>اندھیری تصویر اپ لوڈ کریں اور سلائیڈر کو جمع پندرہ فیصد تک لے جائیں۔ پری ویو دیکھیں: موضوع واضح نظر آنا چاہیے اور روشن حصوں میں تفصیل باقی رہنی چاہیے۔</p>\n<p>اگر تصویر اب بھی بہت اندھیری ہو تو سلائیڈر کو پانچ فیصد کے چھوٹے قدموں میں بڑھائیں۔ ہر قدم تھوڑی سی روشنی بڑھاتا ہے، اور پری ویو بتاتا ہے کہ کب رکنا ہے۔</p>\n<p>آگے بڑھتے ہوئے روشن حصوں پر نظر رکھیں۔ پیشانی، آسمان اور سفید سطحیں سب سے پہلے پھٹتی ہیں، اور سفید دھبوں والی تصویر اندھیری تصویر سے بدتر لگتی ہے۔</p>\n<p>اگر روشن کرنے کے بعد تصویر پھیکی لگے تو کنٹراسٹ شامل کریں۔ <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> کھولیں اور گہرائی واپس لانے کے لیے تھوڑا سا اضافہ کریں۔</p>\n<h2 id=\"darkening-a-bright-photo\">زیادہ روشن تصویر کو اندھیرا کرنا</h2>\n<p>بہت روشن تصویر کے لیے سلائیڈر کو بائیں کھینچیں۔ منفی پندرہ یا منفی تیس فیصد جیسی منفی اقدار سائے گہرے کر کے تصویر کی دولت واپس لاتی ہیں۔</p>\n<p>اندھیرا کرتے وقت سائے دیکھتے رہیں۔ ان میں گہرائی آنی چاہیے، مگر وہ مکمل سیاہ دھبے نہ بنیں جن میں کوئی تفصیل نہ ہو۔</p>\n<p>اندھیرا کرنا اس وقت بھی مدد کرتا ہے جب تصویر کے اوپر تحریر رکھنی ہو۔ اندھیری تصویر پر سفید تحریر پڑھنے میں آسان ہوتی ہے، جو سلائیڈز، پوسٹرز اور سوشل گرافکس کے لیے موزوں ہے۔</p>\n<p>اگر آسمان بہت روشن ہو اور اگلا حصہ بہت اندھیرا ہو تو سمجھوتا قبول کریں۔ چمک سب کچھ ایک ساتھ بدلتی ہے، اس لیے کسی ایک سمت سے دونوں حصے درست نہیں ہوتے۔</p>\n<h2 id=\"fixing-a-screenshot\">اندھیری اسکرین شاٹ کو ٹھیک کرنا</h2>\n<p>محفوظ کرنے کا مرحلہ چھوڑنے کے لیے اسکرین شاٹ کو کنٹرول اور وی دبا کر براہ راست چپکائیں۔ تصویر فوراً ایڈیٹر میں آ جاتی ہے اور روشن کرنے کے لیے تیار ہوتی ہے۔</p>\n<p>چمک اتنی بڑھائیں کہ تحریر صاف ہو اور پس منظر سفید ہو۔ صاف سفید پس منظر اور گہری تحریر والا دستاویز پڑھنے اور چھاپنے میں آسان ہوتا ہے۔</p>\n<p>اندھیرے حصوں میں شور سے ہوشیار رہیں۔ بہت زیادہ روشن کی گئی اسکرین شاٹ میں ہلکے بلاک جیسے نشان نظر آ سکتے ہیں، خاص طور پر اگر جے پی ای جی پہلے ہی کمپریس ہو چکا ہو۔</p>\n<p>اسکرین شاٹس کو پی این جی میں ایکسپورٹ کریں۔ نقصان سے پاک فارمیٹ چھوٹی تحریر کو تیز رکھتا ہے، جو اس وقت اہم ہے جب اسکرین شاٹ کوئی سیٹنگ یا غلطی کا پیغام دکھائے۔</p>\n<h2 id=\"previewing\">ڈاؤن لوڈ سے پہلے پری ویو</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پری ویو دیکھیں۔ جانچیں کہ تصویر قدرتی روشن لگے، کوئی روشن حصہ سفید نہ ہو گیا ہو اور موضوع واضح نظر آتا ہو۔</p>\n<p>تبدیلی جانچنے کے لیے اسپلٹ موازنہ استعمال کریں۔ یہ اصل اور تبدیل شدہ نسخہ ساتھ دکھاتا ہے، اس لیے آپ بالکل دیکھ سکتے ہیں کہ چمک نے کیا کیا۔</p>\n<p>روشن حصوں کو مکمل سائز میں زوم کر کے دیکھیں۔ آسمان یا پیشانی چھوٹے پری ویو میں ٹھیک لگے مگر بڑے سائز میں پھٹی ہوئی نکلے۔</p>\n<p>اگر نتیجہ دھلا ہوا لگے تو سلائیڈر پانچ فیصد کم کریں اور دوبارہ دیکھیں۔ چھوٹی کمی اکثر تفصیل واپس لے آتی ہے، بغیر تصویر کو دوبارہ اندھیرا کیے۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ کا انتخاب</h2>\n<p>بانٹنے والی تصویروں کے لیے جے پی جی چنیں۔ یہ فائل کا حجم چھوٹا رکھتا ہے، ہر جگہ کام کرتا ہے اور اعلیٰ معیار کی سیٹنگ روشن تصویر کو صاف رکھتی ہے۔</p>\n<p>تحریر والی اسکرین شاٹس اور گرافکس کے لیے پی این جی چنیں۔ پی این جی نقصان سے پاک ہے، اس لیے حروف کے کنارے تیز رہتے ہیں اور ضرورت ہو تو شفافیت بھی بچ جاتی ہے۔</p>\n<p>چھوٹی فائل اور اچھا معیار چاہتے ہوں تو ویب پی چنیں۔ یہ ویب تصاویر کے لیے اچھا کام کرتا ہے، اگرچہ چند پرانے نظام اب بھی اسے رد کر دیتے ہیں۔</p>\n<p>یاد رکھیں کہ پی این جی کے لیے معیار والا سلائیڈر چھپ جاتا ہے، کیونکہ پی این جی نقصان سے پاک ہے اور اس کی کوئی معیار کی سیٹنگ نہیں ہوتی۔ یہ عام رویہ ہے، ٹول کا مسئلہ نہیں۔</p>\n<h2 id=\"adjusting-on-mobile\">فون یا ٹیبلٹ پر چمک درست کرنا</h2>\n<p>یہ ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ اندھیری تصویر اسی فون پر ٹھیک کر سکتے ہیں جس سے وہ لی گئی ہو۔ گیلری سے اپ لوڈ کریں، سلائیڈر انگلی سے کھینچیں اور ڈاؤن لوڈ کریں۔</p>\n<p>انگلی سے سلائیڈر کھینچنا ماؤس سے کم درست ہوتا ہے۔ درست اقدار کے لیے فوری پری سیٹس استعمال کریں، پھر چھوٹی حرکتوں سے باریک درستی کریں۔</p>\n<p>ڈاؤن لوڈ سے پہلے پری ویو مکمل سائز میں دیکھیں۔ چھوٹی فون اسکرین پر ٹھیک لگنے والی تبدیلی کمپیوٹر پر بہت زیادہ نکل سکتی ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائلیں آپ کے معمول کے ڈاؤن لوڈ فولڈر میں جاتی ہیں۔ وہاں سے روشن تصویر کو براہ راست چیٹ ایپ، ای میل یا سوشل پوسٹ پر بانٹ سکتے ہیں۔</p>\n<h2 id=\"troubleshooting\">عام چمک کے مسائل کا حل</h2>\n<p>اگر تصویر دھلی ہوئی لگے تو سلائیڈر بہت اونچا ہے۔ اسے چھوٹے قدموں میں کم کریں، جب تک روشن حصوں میں تفصیل واپس نہ آ جائے، پھر سائے دیکھیں۔</p>\n<p>اگر روشن کرنے کے بعد بھی تصویر اندھیری رہے تو اصل تصویر بہت زیادہ اندھیری ہو سکتی ہے۔ تقریباً سیاہ تصویر صرف چمک سے ٹھیک نہیں ہوتی، اور دوبارہ تصویر لینا بہتر ہو سکتا ہے۔</p>\n<p>اگر سائے میں شور نظر آئے تو چمک اصل تصویر کے لیے بہت زیادہ ہے۔ سلائیڈر کم کریں اور قدرے اندھیری تصویر قبول کریں، یا بہتر اصل تصویر سے شروع کریں۔</p>\n<p>اگر پری ویو ڈاؤن لوڈ سے مختلف لگے تو ایکسپورٹ فارمیٹ اور معیار دیکھیں۔ جے پی جی کی کم معیار کی سیٹنگ پوری تصویر کو نرم کر دیتی ہے، چمک سمیت۔</p>\n<h2 id=\"brightness-plus-contrast\">چمک اور کنٹراسٹ: عام جوڑی</h2>\n<p>جو تصویر اندھیری اور پھیکی دونوں ہو، اسے چمک اور کنٹراسٹ دونوں چاہئیں۔ پہلے روشن کریں تاکہ مجموعی سطح اوپر آئے، پھر کنٹراسٹ شامل کریں تاکہ گہرائی واپس آئے۔</p>\n<p>روشن کرنے کے بعد اگر تصویر بھوری اور بے جان لگے تو <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> استعمال کریں۔ تھوڑا سا کنٹراسٹ سائے اور روشن حصے واپس لاتا ہے۔</p>\n<p>مراحل اسی ترتیب میں کریں: پہلے چمک، پھر کنٹراسٹ۔ الٹی ترتیب سے کنٹراسٹ کا اندازہ مشکل ہو جاتا ہے، کیونکہ تصویر اب بھی اندھیری ہوتی ہے۔</p>\n<p>ہر مرحلے کے بعد موازنے والی نظر دیکھیں۔ اسپلٹ نظر بالکل دکھاتی ہے کہ ہر تبدیلی نے کیا کیا، اس لیے جب تصویر درست لگے تو رک جائیں۔</p>\n<h2 id=\"saving-settings\">اگلی بار کے لیے سیٹنگز محفوظ کرنا</h2>\n<p>ملتی جلتی تصویروں کے لیے کام کرنے والی چمک کی قدر لکھ لیں۔ اندرونی مناظر کے لیے جمع بیس فیصد جیسی مختصر نوٹ اگلی بار اندازہ لگانے سے بچاتی ہے۔</p>\n<p>ایک ہی روشنی میں لی گئی تصویروں کے بیچ کے لیے ایک ہی قدر استعمال کریں۔ پورے سیٹ میں مستقل چمک پیشہ ورانہ لگتی ہے، جبکہ ملی جلی قدریں بے ترتیب لگتی ہیں۔</p>\n<p>اصل فائلیں رکھیں۔ ایک تصویر کے لیے کام کرنے والی چمک کی قدر دوسری کے لیے موزوں نہ ہو، اور اصل فائل سے آپ بغیر اضافی نقصان کے دوسری سطح آزما سکتے ہیں۔</p>\n<p>اپنی نوٹس کبھی کبھار دیکھتے رہیں۔ جیسے جیسے آپ کا کیمرہ اور روشنی بہتر ہوتی ہے، درکار چمک کی قدریں بھی بدلتی ہیں اور پرانی نوٹس گمراہ کر سکتی ہیں۔</p>\n<h2 id=\"quick-tips\">بہتر چمک کے لیے فوری نکات</h2>\n<p>چھوٹے قدموں میں روشن کریں۔ ایک وقت میں پانچ فیصد کی تبدیلی آپ کو قابو دیتی ہے، جبکہ بڑی چھلانگ درست قدر سے آگے نکل سکتی ہے۔</p>\n<p>صرف سائے نہیں، روشن حصے بھی دیکھیں۔ تصویر اس وقت زیادہ روشن ہوتی ہے جب روشن حصے تفصیل کھو دیں، چاہے اندھیرے حصے اچھے لگیں۔</p>\n<p>ہر بار موازنے والی نظر استعمال کریں۔ اصل کے ساتھ تبدیل شدہ نسخہ کی ایک تیز نظر ان غلطیوں کو پکڑ لیتی ہے جو چھوٹا پری ویو چھپاتا ہے۔</p>\n<p>اصل تصویر بغیر تبدیلی کے محفوظ کریں۔ ایک بار چمک کی تبدیلی ایکسپورٹ میں شامل ہو جائے تو اس فائل سے واپس نہیں ہو سکتی۔</p>\n<h2 id=\"brightening-for-presentation\">پریزنٹیشن کے لیے تصویر روشن کرنا</h2>\n<p>سلائیڈ پر استعمال ہونے والی تصویر اتنی روشن ہونی چاہیے کہ کمرے کے پیچھے سے نظر آئے۔ بڑی اسکرین پر اندھیری تصویر دھندلی لگتی ہے، جبکہ اچھی روشن تصویر صاف پڑھی جاتی ہے۔</p>\n<p>سلائیڈ کی تصویروں کو فیڈ کے مقابلے میں تھوڑا زیادہ روشن کریں۔ پروجیکٹر رنگ دھو دیتا ہے اور چمک کم کر دیتا ہے، اس لیے لیپ ٹاپ پر ٹھیک لگنے والی تصویر وہاں پھیکی لگ سکتی ہے۔</p>\n<p>اگر ممکن ہو تو تصویر اصل پروجیکٹر پر دیکھیں۔ ایک آزمائشی سلائیڈ بتاتی ہے کہ کمرے کی روشنی میں چمک قائم رہتی ہے یا نہیں، جہاں روشنی آپ کی میز سے بہت مختلف ہوتی ہے۔</p>\n<p>سلائیڈ بھر میں چمک یکساں رکھیں۔ ایک کونے میں روشن اور دوسرے میں اندھیری تصویر سامعین کی توجہ اوپر لکھی تحریر سے ہٹا دیتی ہے۔</p>\n<h2 id=\"brightening-old-scans\">پرانے اسکین شدہ فوٹو روشن کرنا</h2>\n<p>پرانے اسکین شدہ فوٹو اکثر اندھیرے اور پھیکے ہوتے ہیں۔ عمر پرنٹ کو دھندلا دیتی ہے، اسکینر رنگوں کو غلط پڑھتا ہے اور نتیجہ بھوری، دھندلی تصویر ہوتا ہے جسے روشنی چاہیے۔</p>\n<p>چمک چھوٹے قدموں میں بڑھائیں اور چہروں پر نظر رکھیں۔ مقصد وہ تصویر ہے جو اصل پرنٹ کے نئے ہونے پر لگتی تھی، نہ کہ دھلی ہوئی تصویر۔</p>\n<p>پرانے اسکینز کو اکثر چمک کے ساتھ کنٹراسٹ بھی چاہیے۔ پھیکے پرنٹ میں رنگوں کی حد کم ہوتی ہے، اس لیے چمک کا اضافہ اور کنٹراسٹ کا تھوڑا سا بڑھاوا گہرائی واپس لاتا ہے۔</p>\n<p>بہترین اسکین سے کام کریں۔ زیادہ ریزولوشن والا اسکین کہیں بہتر روشن ہوتا ہے، کیونکہ تبدیلی کو ظاہر کرنے کے لیے اس میں زیادہ تفصیل ہوتی ہے۔</p>\n<p>موازنے کے لیے <a href=\"/ur/blog/brightness-vs-exposure-vs-contrast/\">Brightness vs Exposure vs Contrast: Editing Basics</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-brightness-editor-rehnumai/\">Image Brightness Editor: Complete Guide</a> دیکھیں، اور پھیکی تصویر کو ٹھیک کرنے کے لیے کنٹراسٹ والا ایڈیٹر استعمال کریں۔</p>\n<ul>\n<li>اپنی تصویر ڈراپ زون میں کھینچ کر، ڈیوائس سے چن کر، یا کنٹرول اور وی دبا کر اسکرین شاٹ چپکا کر اپ لوڈ کریں۔</li>\n<li>روشن کرنے کے لیے برائٹنس لیول سلائیڈر کو دائیں اور اندھیرا کرنے کے لیے بائیں کھینچیں، براہ راست پری ویو دیکھتے ہوئے۔</li>\n<li>ایک کلک کی آزمائش کے لیے فوری پری سیٹ آزمائیں، پھر اگر نتیجہ قریب ہو مگر بالکل درست نہ ہو تو سلائیڈر سے باریک درستی کریں۔</li>\n<li>اصل سے موازنہ کرنے کے لیے بعد، پہلے، اسپلٹ موازنہ یا فل اسکرین موازنے کے طریقے استعمال کریں۔</li>\n<li>ایکسپورٹ فارمیٹ اور معیار چنیں، پھر درست شدہ تصویر محفوظ کرنے کے لیے ڈاؤن لوڈ پر کلک کریں۔</li>\n</ul>";

export const FAQS: BlogArticleFaq[] = [{"question":"میں اپنے فون پر تصویر کیسے روشن کروں؟","answer":"اپنے فون کے براؤزر میں Image Brightness Editor کھولیں، گیلری سے تصویر اپ لوڈ کریں اور انگلی سے سلائیڈر کو دائیں کھینچیں۔ درست قدر کے لیے فوری پری سیٹ استعمال کریں، موازنے والی نظر سے نتیجہ دیکھیں اور پھر ڈاؤن لوڈ کریں۔"},{"question":"اندھیرے اندرونی فوٹو کے لیے کون سی چمک کی قدر استعمال کروں؟","answer":"جمع پندرہ فیصد سے شروع کریں، جو ٹول کی پری ویو قدر ہے، اور پانچ فیصد کے قدموں میں بڑھائیں جب تک موضوع واضح نظر نہ آئے۔ زیادہ تر اندرونی تصویروں کو پندرہ سے تیس فیصد چاہیے۔ روشن حصے سفید ہونے سے پہلے رک جائیں۔"},{"question":"کیا میں بہت زیادہ روشن تصویر کو اندھیرا کر سکتا ہوں؟","answer":"جی ہاں۔ سلائیڈر کو بائیں کھینچیں، منفی پندرہ یا منفی تیس فیصد جیسی منفی اقدار تک۔ اندھیرا کرنا سائے گہرا کرتا ہے اور زیادہ روشن تصویر کی دولت واپس لاتا ہے۔ سائے دیکھتے رہیں تاکہ وہ مکمل سیاہ نہ بن جائیں۔"},{"question":"میری روشن کی گئی تصویر میں دانے دار شور کیوں نظر آتا ہے؟","answer":"چمک اس شور کو ظاہر کر دیتی ہے جو سائے میں چھپا تھا، اور جے پی جی کمپریشن اسے مزید بڑھا دیتا ہے۔ سلائیڈر کم کریں اور قدرے اندھیری تصویر قبول کریں، یا اچھی روشنی میں لی گئی بہتر اصل تصویر سے شروع کریں۔"},{"question":"کیا چمک کنٹراسٹ سے پہلے درست کروں یا بعد میں؟","answer":"پہلے چمک، پھر کنٹراسٹ۔ چمک مجموعی سطح اوپر لاتی ہے اور کنٹراسٹ وہ گہرائی واپس لاتا ہے جو چمک دھو سکتی ہے۔ اس ترتیب سے ہر تبدیلی کا اندازہ لگانا آسان ہوتا ہے۔"},{"question":"کیا میں ڈاؤن لوڈ کے بعد چمک کی تبدیلی واپس کر سکتا ہوں؟","answer":"ڈاؤن لوڈ شدہ فائل سے نہیں، کیونکہ تبدیلی ایکسپورٹ میں شامل ہو جاتی ہے۔ اصل تصویر رکھیں تاکہ آپ دوسری چمک کی سطح آزما سکیں۔ ٹول میں، ڈاؤن لوڈ سے پہلے صفر پر واپس جانے کے لیے ری سیٹ کا آپشن استعمال کریں۔"}];
